    /** A due-total as shown: at most {@code cap}, when there is one. */
    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
        return cap == null ? due : due.min(cap);
    }

    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when it is dated
     * within one of its person's holds, or held itself, or its person's retirement date is reached on
     * {@code today}, and no statement binds it. */
    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
        return countsAs(claim, claim.getStatus(), person, today);
    }

    /** Whether the claim counts in what its person has claimed on the sheet's {@code today}: as it counts in
     * the live totals (see {@link #countsLive}), but a hold, the person's or the claim's own, does not take it out. */
    public static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
        ClaimStatus status = claim.getStatus();
        if (!status.counts()) return false;
        if (!status.isOpen()) return true;
        if (claim.isDeferredOn(today)) return false;
        return claim.isStated() || !person.isRetiredOn(today);
    }

    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
     * {@code status} (see {@link #countsLive}). */
    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
        if (!status.counts()) return false;
        if (!status.isOpen()) return true;
        if (claim.isDeferredOn(today)) return false;
        boolean bound = claim.isStated();
        return bound || !(claim.isHeld() || person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
    }

    /** What a sheet's figures are worked out from: its today, the policy date, rates and dated settings in
     * force, and its claims. {@link #live} is the sheet as it stands; a sheet as it stood on an earlier
     * date gives its own. */
      this.approverInputs.update(({ [person.id]: _, ...rest }) => rest);
    } catch {
      if (this.sheet() !== sheet) return;
      this.rowErrors.update((errors) => ({ ...errors, [person.id]: 'The approver could not be set.' }));
    }
  }

  /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED, but not an OPEN claim
   *  deferred on the sheet's today, nor OPEN or PENDING when it is dated within one of its person's
   *  holds, or held itself, or its person's retirement date is reached on the sheet's today, and no statement binds it. */
  private countsLive(claim: Claim, person: Person): boolean {
    return this.countsAs(claim, claim.status, person);
  }

  /** Whether the claim counts in what its person has claimed: as countsLive says, but a hold, the
   *  person's or the claim's own, does not take it out. */
  private countsClaimed(claim: Claim, person: Person): boolean {
    if (!counts(claim)) return false;
    if (!isOpen(claim)) return true;
    const today = this.session.today();
    if (deferred(claim, today)) return false;
    const retired = person.retiredFrom !== null && today !== null && person.retiredFrom <= today;
    return claim.stated || !retired;
  }

  /** Whether the claim would count in the live totals were its status `status` (see countsLive). */
  private countsAs(claim: Claim, status: ClaimStatus, person: Person): boolean {
    const as = { ...claim, status };
    if (!counts(as)) return false;
    if (!isOpen(as)) return true;
    if (deferred(claim, this.session.today())) return false;
    const bound = claim.stated;
    const today = this.session.today();
    const retired = person.retiredFrom !== null && today !== null && person.retiredFrom <= today;
    return bound || !(claim.held || heldOn(person.holds, claim.date) || retired);
  }

  /** Whether the claim counts in a period ending on `end`: by the status it had at the end of
   *  that day (a claim added after does not count), otherwise as the live rules say while it is still
   *  open now (a claim since settled or voided is left out by no hold or deferral). */
  private countsAtEnd(claim: Claim, person: Person, end: string): boolean {
    const status = statusOn(claim, end);
    if (status === null) return false;
    if (!isOpen(claim)) return counts({ ...claim, status });
    return this.countsAs(claim, status, person);
  }

  /** Whether the person is active: they have an OPEN or PENDING claim that counts, dated within the
   *  30 days up to and including the sheet's today. */
  protected isActive(person: Person): boolean {
    const today = this.session.today();
    if (today === null) return false;
    const from = daysBefore(today, 29);
    return this.claimsOf(person.id).some(
      (c) => isOpen(c) && this.countsLive(c, person) && from <= c.date && c.date <= today,
    );
  }

  protected claimedOf(person: Person): string {
    return money(this.claimedCentsOf(person));
  }

  /** What the person's OPEN, PENDING and SETTLED claims add up to, held ones included (see
   *  countsClaimed); drafts, voided claims and corrections do not count. */
  private claimedCentsOf(person: Person): number {
    return this.claimsOf(person.id).reduce(
      (sum, c) => sum + (this.countsClaimed(c, person) && !isCorrection(c) ? cents(c.amount) : 0),
      0,
    );
  }

  /** The grade's rate in force on the sheet's today. */
  private rateOf(grade: Grade | null): string | null {
    const today = this.session.today();
    return today === null || grade === null ? null : rateOn(this.rates(), grade, today);
  }

  /** What decides how the person's claims round. */
  private roundingOf(personId: number): Rounding {
    return { modes: this.roundings(), policyDate: this.policyDateInForce(), claims: this.claimsOf(personId) };
  }
